<?php declare(strict_types=1);namespace StudPulse\Http;use StudPulse\Database\DB;use StudPulse\Integrations\MpeiMailConnections;use StudPulse\Security\Auth;use StudPulse\Security\Crypto;final class Idempotency{public static function execute(Auth$a,Request$r,callable$handler,?array$journal=null,bool$external=false):mixed{$key=$r->header('Idempotency-Key');if(!preg_match('/^[A-Za-z0-9_-]{16,100}$/',$key)){throw new ApiError(400,'IDEMPOTENCY_REQUIRED','Укажите Idempotency-Key (16–100 символов)');}$files=[];foreach(Request::uploadedFiles()as$f){$temp=$f['tmp_name']??null;$checksum=is_string($temp)&&is_uploaded_file($temp)?hash_file('sha256',$temp):null;if(isset($_FILES['file'])){$files['file']=$checksum;}else{$files[]=[$f['name']??null,$checksum,$f['error']??null];}}$membership=$journal??$a->membership;$permissionContext=[$membership['id']??null,$membership['group_id']??null,$membership['term_id']??null,$membership['role']??null,$membership['valid_to']??null,$a->apiToken['id']??'browser'];$payload=$r->method.$r->path.json_encode($r->body,JSON_THROW_ON_ERROR).json_encode($files,JSON_THROW_ON_ERROR).json_encode($permissionContext,JSON_THROW_ON_ERROR);$privateBrowserRequest=str_starts_with($r->path,'/api/v1/mail/')||$r->path==='/api/v1/attendance/qr';if($privateBrowserRequest)$a->browserOnly();$digest=$privateBrowserRequest?Crypto::hash($a->session['id'].':'.$payload):hash('sha256',$payload);$hash=hash('sha256',$key);$execute=function()use($a,$r,$handler,$hash,$digest){DB::run('INSERT IGNORE INTO idempotency_keys(user_id,key_hash,request_hash,expires_at) VALUES(?,?,?,DATE_ADD(UTC_TIMESTAMP(6),INTERVAL 1 DAY))',[$a->user['id'],$hash,$digest]);$row=DB::one('SELECT * FROM idempotency_keys WHERE user_id=? AND key_hash=? FOR UPDATE',[$a->user['id'],$hash]);if(!hash_equals($row['request_hash'],$digest)){throw new ApiError(409,'IDEMPOTENCY_CONFLICT','Этот ключ уже использован для другого запроса');}if($row['response_json']!==null){$stored=json_decode($row['response_json'],true,32,JSON_THROW_ON_ERROR);if(str_starts_with($r->path,'/api/v1/mail/drafts/')&&isset($stored['sealed'])){$reply=json_decode(Crypto::decrypt($stored['sealed']),true,32,JSON_THROW_ON_ERROR);if(($reply['hash']??'')!==$hash)throw new \RuntimeException('Invalid draft operation binding');if(!MpeiMailConnections::find($a->session['id'])){throw new ApiError(403,'MPEI_MAIL_CONNECT','Подключение к почте уже завершено.');}return$reply['result'];}return$stored;}if($r->path==='/api/v1/mail/send'){DB::run('UPDATE idempotency_keys SET response_json=? WHERE user_id=? AND key_hash=?',[json_encode(['sent'=>false,'deliveryUnknown'=>true],JSON_THROW_ON_ERROR),$a->user['id'],$hash]);}$result=$handler();$stored=$result;if($r->path==='/api/v1/tokens'&&is_array($stored)){unset($stored['token']);$stored['message']='Токен уже был показан один раз. Создайте новый, если не сохранили его.';}if($r->path==='/api/v1/calendar/subscriptions'&&is_array($stored)){unset($stored['url']);$stored['message']='Ссылка уже была показана один раз. Создайте новую, если не сохранили её.';}if($r->path==='/api/v1/integrations/google/connect'&&is_array($stored)){unset($stored['url']);$stored['message']='OAuth ссылка уже выдана. Начните новое подключение при необходимости.';}if(str_starts_with($r->path,'/api/v1/mail/drafts/')){$stored=['sealed'=>Crypto::encrypt(json_encode(['hash'=>$hash,'result'=>$result],JSON_THROW_ON_ERROR))];}DB::run('UPDATE idempotency_keys SET response_json=?,response_status=200 WHERE user_id=? AND key_hash=?',[json_encode($stored,JSON_THROW_ON_ERROR),$a->user['id'],$hash]);return$result;};if(!$external)return DB::transaction($execute);$lock='idem:'.substr(hash('sha256',$a->user['id'].$hash),0,59);if(!(int)DB::one('SELECT GET_LOCK(?,0) AS acquired',[$lock])['acquired']){throw new ApiError(409,'IDEMPOTENCY_IN_PROGRESS','Запрос ещё выполняется');}try{return$execute();}finally{DB::run('SELECT RELEASE_LOCK(?)',[$lock]);}}}